ထည့်စရာ မလိုတဲ့အတွက် လိုအပ်ရင် တန်ဖိုးတွေကို ပေါင်းနှုတ်မြှောက်စား လုပ်လို့ရပါတယ်။ border
အတွက်တော့ 1px solid red လို့ ပေးထားပါတယ်။ px Unit ထည့်ပေးထားပါတယ်။ ပေးလို့ရပါ
တယ်။ Quote အဖွင့်အပိတ်ထဲမှာတော့ ဖြစ်ရပါတယ်။
CSS တွေ များလာတဲ့အခါ ပြင်ဆင်ထိမ်းသိမ်းရလွယ်အောင် ဒုတိယ ရေးနည်းအနေနဲ့ အခုလို ခွဲရေးထား
သင့်ပါတယ်။
const styles = {
 toolbar: {
 marginBottom: 20,
 border: '1px solid red',
 }
}
ပြီးတော့မှ လိုတဲ့နေရာမှာ အခုလို ထည့်သုံးလိုက်တာ ပိုကောင်းပါတယ်။
render() {
 return (
 <div style={styles.toolbar}>
 {this.props.children}
 </div>
 );
}

။ တစ်ခုထက်ပိုတဲ့ Style သတ်မှတ်ချက်
ကို Component မှာ တွဲသုံးချင်လည်း ရပါတယ်။ ဥပမာ - Style က ဒီလိုသတ်မှတ်ထားတယ် ဆိုပါစို့။

toolbar: {
 marginBottom: 20,
 border: '1px solid red',
 },
 dark: {
 background: 'purple',
 color: 'white',
 }
}
Component မှာ အခုလို အလွယ်တစ်ကူ ယူသုံးလိုက်လို့ ရပါတယ်။
render() {
 return (
 <div style={styles.toolbar, styles.dark}>
 {this.props.children}
 </div>
 );
}
တွဲသုံးချင်တဲ့ Style တွေကို Comma လေးခံပြီး ထည့်သွားလိုက်တာပါပဲ။
နောက်တစ်နည်းဖြစ်တဲ့ Styled Component ကတေ
ာ့ ပရောဂျက်ထဲမှာ အသင့်မပါပါဘူး။ Package ထပ်
ထည့်ပြီးမှ အသုံးပြုလို့ရမှာဖြစ်လို့ ဒီတစ်နည်းကိုတော့ ချန်ထားလိုက်ပါမယ်။ React နဲ့ပက်သက်ပြီး
ကောင်းကောင်း ကျင်လည်လာပြီဆိုတော့မှ ကိုယ့်ဘာသာ ဆက်လေ့လာရမှာပါ။

